{
      // openBets duplicate-check chain (.select.eq.eq.is) resolves with
      // existingBetRows; the existing-bet branch only fires when the test
      // seeds at least one row.
      select: () => builder,
      insert: async (values: CapturedInsertValues) => {
        supabaseInserts.push({ table, values })
        if (table === 'steam_accounts') {
          if (steamAccountInsertResult.throwError) {
            return await Promise.reject(steamAccountInsertResult.throwError)
          }
          return await Promise.resolve({ ...steamAccountInsertResult })
        }
        return await Promise.resolve({ data: null, error: null, throwError: null })
      },
      update: (values: CapturedUpdateValues) => {
        supabaseUpdates.push({ table, values })
        return builder
      },
      upsert: async () => await Promise.resolve({ data: null, error: null }),
      eq: () => builder,
      is: async () => await Promise.resolve({ data: [...existingBetRows], error: null }),
      neq: () => builder,
      not: () => builder,
      gte: () => builder,
      order: () => builder,
      limit: async () => await Promise.resolve({ data: [...existingBetRows], error: null }),
      single: async () => {
        if (table === 'matches') {
          return await Promise.resolve({ ...matchPredictionLookup })
        }
        return await Promise.resolve({ data: null, error: { message: 'not found' } })
      },
      maybeSingle: async () => {
        if (table === 'steam_accounts') {
          steamAccountSelectCalls.push(Date.now())
        }
        return await Promise.resolve({ ...steamAccountLookup })
      },
      match: async () => await Promise.resolve({ data: null, error: null }),
      then: async (onFulfilled) =>
        await Promise.resolve({ data: [...existingBetRows], error: null }).then(onFulfilled),
    }

new Promise((resolve, _reject) => {
      if (!this.isDota2Ready() || !this.isSteamClientLoggedOn()) {
        return
      }

      const games: SteamMatchDetails[] = []
      const startGame = 90
      let listenerRemoved = false
      let callbackNotSpecificGames: ((data: SourceTvGamesResponse | null) => void) | null = null

      const removeListener = () => {
        if (!listenerRemoved) {
          listenerRemoved = true
          this.dota2.removeListener('sourceTVGamesData', callbackNotSpecificGames)
        }
        callbackNotSpecificGames = null
      }

      // node-dota2 emits null for malformed GC responses; ignore it before accumulation.
      callbackNotSpecificGames = (data) => {
        if (!isBadSourceTvGamesResponse(data)) {
          games.push(...data.game_list.filter((game) => game.players.length > 0))
          // add match ids to unique set
          if (data.league_id === 0 && startGame === data.start_game) {
            removeListener()
            resolve(this.filterUniqueGames(games))
          }
        }
      }

      this.dota2.on('sourceTVGamesData', callbackNotSpecificGames)

      // Timeout to clean up the listener if the promise never resolves
      setTimeout(() => {
        removeListener()
      }, 30_000)

      for (let start = 0; start < 100; start += 10) {
        setTimeout(() => {
          try {
            this.dota2.requestSourceTVGames({ start_game: start })
          } catch (error) {
            logger.error('Error in Dota2Client.requestSourceTVGames:', error)
          }
        }, 50 * start)
      }
    })

async function notablePlayers({
  client,
  locale,
  twitchChannelId,
  currentMatchId,
  players,
  enableFlags,
  steam32Id,
  heroesStatus,
  rosterSource,
}: {
  client?: SocketClient
  locale: string
  twitchChannelId: string
  currentMatchId?: string
  players?: RosterPlayer[]
  enableFlags?: boolean
  steam32Id: number | null
  heroesStatus?: HeroesStatus
  rosterSource?: RosterSource
}) {
  // Draft-only path: the players passed in are OCR'd draft names with no ranks
  // or hero data, so skip getPlayers (which would fire a needless Steam getCards
  // lookup) and use them directly.
  const { matchPlayers, accountIds, gameMode } = heroesStatus
    ? {
        accountIds: (players ?? []).map((p) => p.accountId ?? 0),
        gameMode: undefined,
        matchPlayers: players ?? [],
      }
    : await getPlayers({
        currentMatchId,
        locale,
        players,
      })

  const mongo = MongoDBSingleton
  const db = await mongo.connect()

  try {
    const mode =
      gameMode !== undefined && gameMode !== 0
        ? await db
            .collection('gameModes')
            .findOne({ id: gameMode }, { projection: { _id: 0, name: 1 } })
        : { name: null }

    // Draft-only players have accountid 0, which can never match a stored
    // record, so skip the lookup entirely when there are no real account ids.
    const hasRealAccounts = accountIds.some((id) => id !== 0)
    const nps = hasRealAccounts
      ? await db
          .collection<NotablePlayers>('notablePlayers')
          .find(
            {
              account_id: {
                $in: accountIds,
              },
              channel: {
                $in: [null, twitchChannelId],
              },
            },
            {
              projection: {
                _id: 0,
                account_id: 1,
                country_code: 1,
                name: 1,
              },
            }
          )
          .toArray()
      : []

    // SourceTV gives authoritative account_id + hero_id pairs but no display identity. Resolve
    // names and optional countries by account ID instead of mixing OCR text into that roster.
    const steamSummaries =
      rosterSource === 'sourcetv'
        ? await getSteamPlayerSummaries(accountIds)
        : new Map<number, SteamPlayerSummary>()

    // Description text. When only draft player names are available (no heroes
    // yet) there are no ranks to average, so skip the avg lookup entirely.
    const avg = heroesStatus
      ? null
      : await calculateAvg({
          currentMatchId,
          locale,
          players,
        })

    const proPlayers: NotablePlayer[] = []

    // Using for..of loop instead of forEach to properly handle await
    for (const [i, player] of matchPlayers.entries()) {
      const np = nps.find((np) => np.account_id === player.accountId)
      const steamSummary =
        player.accountId === null ? undefined : steamSummaries.get(player.accountId)
      const isCurrentPlayer = player.accountId === steam32Id
      const fallbackHeroId = matchPlayers[i]?.heroId ?? 0
      const playerName =
        firstNonEmptyString(
          np?.name,
          steamSummary?.personaName,
          rosterSource === 'sourcetv' ? undefined : matchPlayers[i]?.playerName
        ) ?? `Player ${i + 1}`

      // Determine hero name based on available data
      let heroName = '?'
      if (
        isCurrentPlayer &&
        client &&
        client.gsi?.hero?.id !== undefined &&
        client.gsi?.hero?.id > -1
      ) {
        heroName = getHeroNameOrColor(client.gsi.hero.id, i)
      } else if (player.slot !== null) {
        heroName = getHeroNameOrColor(player.heroId ?? 0, i)
      }

      const playerData = {
        account_id: player.accountId ?? 0,
        country_code: firstNonEmptyString(np?.country_code, steamSummary?.countryCode) ?? '',
        heroId: player.heroId ?? 0,
        heroName:
          heroName === '?'
            ? fallbackHeroId > 0
              ? getHeroNameOrColor(fallbackHeroId, i)
              : '?'
            : heroName,
        isMe: isCurrentPlayer,
        name: (await moderateText(playerName)) ?? `Player ${i + 1}`,
        position: i,
      }

      // Show a player when they're a tracked pro (np), when a name was detected,
      // or when this is a vision-detected hero (accountId null from the Vision
      // API, which never provides account ids so np can never match). The
      // vision path is the high-MMR roster view, so a confidently-detected hero
      // must not vanish just because its name OCR came back empty.
      const isVisionHero = player.accountId === null && (player.heroId ?? 0) > 0
      const isSourceTvPlayer = rosterSource === 'sourcetv' && player.accountId !== null
      if (
        np !== undefined ||
        isSourceTvPlayer ||
        firstNonEmptyString(matchPlayers[i]?.playerName) !== undefined ||
        isVisionHero
      ) {
        proPlayers.push(playerData)
      }
    }

    let modeText: string
    if (heroesStatus) {
      const noteKey =
        heroesStatus === 'failed' ? 'notablePlayersNoHeroes' : 'notablePlayersWaitingHeroes'
      modeText = `[${t(noteKey, { lng: locale })}]: `
    } else {
      modeText = typeof mode?.name === 'string' ? `${mode.name} [${avg} avg]: ` : `[${avg} avg]: `
    }
    const proPlayersString = proPlayers
      .map((m) => {
        const country: string =
          enableFlags === true && m.country_code.length > 0
            ? `${countryCodeEmoji(m.country_code)} `
            : ''
        // Draft-only: heroes unknown, show names without the "(Hero)" suffix.
        return heroesStatus ? `${country}${m.name}` : `${country}${m.name} (${m.heroName})`
      })
      .join(' · ')

    return {
      description: `${modeText}${proPlayersString || t('noNotable', { lng: locale })}`,
      playerList: proPlayers,
    }
  } finally {
    await mongo.close()
  }
}

async function handleNewUser(providerAccountId: string, botApi: ApiClient) {
  try {
    const stream = await botApi.streams.getStreamByUserId(providerAccountId)
    const streamer = await botApi.users.getUserById(providerAccountId)
    // const follows = botApi.users.getFollowsPaginated({
    //   followedUser: providerAccountId,
    // })
    // const totalFollowerCount = await follows.getTotalCount()

    const data = {
      displayName: streamer?.displayName,
      name: streamer?.name,
      stream_online: !!stream?.startDate,
      stream_start_date: stream?.startDate?.toISOString() ?? null,
    }

    // remove falsy values from data (like displayName: undefined)
    const filteredData = Object.fromEntries(
      Object.entries(data).filter(([_key, value]) => Boolean(value))
    ) as Partial<typeof data>

    let userId: string | null = null
    if (providerAccountId) {
      const { data } = await supabase
        .from('accounts')
        .select('userId')
        .eq('provider', 'twitch')
        .eq('providerAccountId', providerAccountId)
        .single()
      userId = data?.userId ?? null
    }

    console.log({ filteredData, userId })

    if (userId === null || userId.length === 0) {
      logger.error('[USER] 2 Error checking auth', { error: 'No token' })
      return null
    }

    await supabase.from('users').update(filteredData).eq('id', userId)
  } catch (error) {
    console.log(error, 'error on getStreamByUserId')
  }
}

